package com.example.starter.race.api;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 提交选手检查点通过记录请求。
 *
 * @param timingId        全局唯一分段记录ID（第二层幂等键）
 * @param checkpointCode  通过的检查点代码
 * @param elapsedMillis   通过累计耗时（毫秒，1~86400000），必须小于该选手原始完赛耗时
 * @param expectedVersion 客户端所见赛事版本
 * @param requestId       全局唯一请求ID（写操作幂等键）
 */
public record SubmitTimingRequest(
        @NotBlank String timingId,
        @NotBlank String checkpointCode,
        @NotNull @Positive @Max(86_400_000L) Long elapsedMillis,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

/**
 * 分段通过记录响应。
 *
 * @param timingId       全局唯一分段记录ID
 * @param bib            选手参赛号
 * @param checkpointCode 检查点代码
 * @param position       检查点顺序，从1连续递增
 * @param elapsedMillis  通过该检查点的累计耗时（毫秒）
 * @param createdAt      提交时间，Unix毫秒时间戳
 */
public record CheckpointTimingResponse(
        String timingId,
        String bib,
        String checkpointCode,
        int position,
        long elapsedMillis,
        long createdAt
) {
}

package com.example.starter.race.api;

import com.fasterxml.jackson.annotation.JsonInclude;

import java.util.List;

/**
 * 单个选手分段查询响应：按检查点顺序稳定返回每个检查点的通过情况。
 *
 * @param raceId       赛事ID
 * @param bib          参赛号
 * @param version      查询时的赛事版本（只读查询不修改版本）
 * @param finishTimeMs 该选手原始完赛耗时（毫秒）；尚无完赛计时为 null
 * @param checkpoints  按 position 升序的分段明细；未配置检查点的赛事为空列表
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record RunnerTimingResponse(
        String raceId,
        String bib,
        int version,
        Long finishTimeMs,
        List<CheckpointPassResponse> checkpoints
) {
}

package com.example.starter.race.api;

import com.example.starter.race.domain.RaceStatus;
import com.fasterxml.jackson.annotation.JsonInclude;

import java.util.List;

/**
 * 成绩榜响应：即时成绩或封榜只读快照。
 *
 * @param raceId   赛事ID
 * @param version  榜单对应的版本号
 * @param status   OPEN / SEALED
 * @param sealedAt 封榜时间，Unix毫秒时间戳；未封榜为 null
 * @param entries  按展示顺序排列的成绩条目
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record StandingResponse(
        String raceId,
        int version,
        RaceStatus status,
        Long sealedAt,
        List<ResultEntryResponse> entries
) {
}

package com.example.starter.race.api;

import com.example.starter.race.domain.EntryStatus;
import com.fasterxml.jackson.annotation.JsonInclude;

import java.util.List;

/**
 * 成绩榜中的单个条目。
 *
 * @param bib                    参赛号
 * @param rank                   名次（并列同名次并跳号）；非 RANKED 为 null
 * @param status                RANKED / UNTIMED / MISSING_CHECKPOINT / DISQUALIFIED
 * @param finishTimeMs          原始完赛耗时毫秒；计时缺失为 null
 * @param penaltyMs             生效加时合计毫秒数
 * @param totalTimeMs           总耗时毫秒；未排名为 null
 * @param checkpointCount       赛事检查点总数；未配置检查点为 0
 * @param coveredCheckpointCount 该选手已覆盖检查点数量
 * @param missingCheckpoints    缺失检查点代码，按检查点顺序排列；无缺失为空列表
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record ResultEntryResponse(
        String bib,
        Integer rank,
        EntryStatus status,
        Long finishTimeMs,
        long penaltyMs,
        Long totalTimeMs,
        int checkpointCount,
        int coveredCheckpointCount,
        List<String> missingCheckpoints
) {
}

package com.example.starter.race.api;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 单个选手在单个检查点上的分段明细。
 *
 * @param checkpointCode 检查点代码
 * @param position       检查点顺序，从1连续递增
 * @param elapsedMillis  通过累计耗时（毫秒）；尚未通过（缺失检查点）为 null
 * @param timingId       分段记录ID；尚未通过为 null
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record CheckpointPassResponse(
        String checkpointCode,
        int position,
        Long elapsedMillis,
        String timingId
) {
}

package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;

/**
 * 封榜请求；校验版本后原子保存全体选手只读成绩快照并转 SEALED。
 *
 * @param expectedVersion 客户端所见赛事版本
 * @param requestId       全局唯一请求ID（幂等键）
 */
public record SealRaceRequest(
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.persistence;

/**
 * result_snapshot_checkpoint 表行记录：封榜快照中某选手在某检查点的固化明细。
 *
 * @param raceId         所属快照的赛事ID
 * @param bib            参赛号
 * @param checkpointCode 检查点代码
 * @param position       检查点顺序，从1递增
 * @param elapsedMillis  封榜时通过耗时（毫秒）；缺失检查点为 null
 * @param timingId       分段记录ID；缺失检查点为 null
 */
public record SnapshotCheckpointRow(
        String raceId,
        String bib,
        String checkpointCode,
        int position,
        Long elapsedMillis,
        String timingId
) {
}

