153	    @Test
154	    void 封榜后即时成绩返回只读快照且不再随后续变化() {
155	        seedSealedRace();
156	        StandingResponse snapshot = raceService.getResults(RACE);
157	
158	        // 直接在库内写入“封榜后才出现”的选手：只读快照与查询结果都不应受影响
159	        jdbcTemplate.update(
160	                "INSERT INTO runner (race_id, bib, finish_time_ms, created_at, updated_at) "
161	                        + "VALUES (?, 'late', 1, 100, 100)", RACE);
162	
163	        StandingResponse results = raceService.getResults(RACE);
164	        StandingResponse snapshotAgain = raceService.getSnapshot(RACE);
165	        assertThat(results).usingRecursiveComparison().isEqualTo(snapshot);
166	        assertThat(snapshotAgain).usingRecursiveComparison().isEqualTo(snapshot);
167	        assertThat(results.entries()).extracting(ResultEntryResponse::bib)
168	                .doesNotContain("late");
169	    }
170	
171	    @Test
172	    void 版本不匹配返回409且版本不变() {
173	        raceService.createRace(new CreateRaceRequest(RACE, "req-create"));
174	        raceService.registerRunner(RACE,
175	                new RegisterRunnerRequest("a", 100L, 1, "req-a"));
176	
177	        assertThatThrownBy(() -> raceService.registerRunner(RACE,
178	                new RegisterRunnerRequest("b", 100L, 1, "req-b-stale")))
179	                .isInstanceOf(ConflictException.class)
180	                .hasMessageContaining("版本冲突");
181	
182	        assertThat(raceService.getResults(RACE).version()).isEqualTo(2);
183	    }
184	
185	    @Test
186	    void 不存在与重复与参数错误分别返回对应异常() {
187	        assertThatThrownBy(() -> raceService.getResults("missing"))
188	                .isInstanceOf(NotFoundException.class);
189	        assertThatThrownBy(() -> raceService.getSnapshot(RACE))
190	                .isInstanceOf(NotFoundException.class);
191	
192	        raceService.createRace(new CreateRaceRequest(RACE, "req-create"));
193	        raceService.registerRunner(RACE,
194	                new RegisterRunnerRequest("a", 100L, 1, "req-a"));
195	
196	        // 参赛号重复
197	        assertThatThrownBy(() -> raceService.registerRunner(RACE,
198	                new RegisterRunnerRequest("a", 100L, 2, "req-a-dup")))
199	                .isInstanceOf(ConflictException.class);
200	
201	        // 赛事ID重复
202	        assertThatThrownBy(() -> raceService.createRace(
203	                new CreateRaceRequest(RACE, "req-create-dup")))
204	                .isInstanceOf(ConflictException.class);
205	
206	        // 修订不存在的选手
207	        assertThatThrownBy(() -> raceService.reviseTime(RACE,
208	                new ReviseTimeRequest("ghost", 100L, 2, "req-ghost")))
209	                .isInstanceOf(NotFoundException.class);
210	
211	        // 加时越界
212	        assertThatThrownBy(() -> raceService.addPenalty(RACE,
213	                new AddPenaltyRequest("p1", "a", "ADD_TIME", 3_600_001L, 2, "req-p1")))
214	                .isInstanceOf(BadRequestException.class);
215	        // 加时缺时长
216	        assertThatThrownBy(() -> raceService.addPenalty(RACE,
217	                new AddPenaltyRequest("p2", "a", "ADD_TIME", null, 2, "req-p2")))
218	                .isInstanceOf(BadRequestException.class);
219	        // 取消资格带时长
220	        assertThatThrownBy(() -> raceService.addPenalty(RACE,
221	                new AddPenaltyRequest("p3", "a", "DISQUALIFY", 1L, 2, "req-p3")))
222	                .isInstanceOf(BadRequestException.class);
223	        // 未知类型
224	        assertThatThrownBy(() -> raceService.addPenalty(RACE,
225	                new AddPenaltyRequest("p4", "a", "UNKNOWN", null, 2, "req-p4")))
226	                .isInstanceOf(BadRequestException.class);
227	        // 处罚不存在 / 重复ID
228	        assertThatThrownBy(() -> raceService.revokePenalty(RACE, "nope",
229	                new RevokePenaltyRequest(2, "req-rev-nope")))
230	                .isInstanceOf(NotFoundException.class);
231	        raceService.addPenalty(RACE,
232	                new AddPenaltyRequest("p5", "a", "ADD_TIME", 10L, 2, "req-p5"));
233	        assertThatThrownBy(() -> raceService.addPenalty(RACE,
234	                new AddPenaltyRequest("p5", "a", "ADD_TIME", 10L, 3, "req-p5-dup")))
235	                .isInstanceOf(ConflictException.class);
236	    }
