238	    @Test
239	    void 重复撤销返回409且历史处罚不被覆盖() {
240	        raceService.createRace(new CreateRaceRequest(RACE, "req-create"));
241	        raceService.registerRunner(RACE,
242	                new RegisterRunnerRequest("a", 100L, 1, "req-a"));
243	        raceService.addPenalty(RACE,
244	                new AddPenaltyRequest("p1", "a", "ADD_TIME", 10L, 2, "req-p1"));
245	        raceService.revokePenalty(RACE, "p1",
246	                new RevokePenaltyRequest(3, "req-rev1"));
247	
248	        assertThatThrownBy(() -> raceService.revokePenalty(RACE, "p1",
249	                new RevokePenaltyRequest(4, "req-rev2")))
250	                .isInstanceOf(ConflictException.class)
251	                .hasMessageContaining("已撤销");
252	    }
253	
254	    @Test
255	    void 同键同参重放原成功结果且不重复变更() {
256	        raceService.createRace(new CreateRaceRequest(RACE, "req-create"));
257	        RegisterRunnerRequest register =
258	                new RegisterRunnerRequest("a", 100L, 1, "req-reg-a");
259	
260	        ServiceResult first = raceService.registerRunner(RACE, register);
261	        ServiceResult replay = raceService.registerRunner(RACE, register);
262	
263	        assertThat(first.status()).isEqualTo(201);
264	        assertThat(replay.status()).isEqualTo(first.status());
265	        assertThat(json(replay.body())).isEqualTo(json(first.body()));
266	        assertThat(raceService.getResults(RACE).version()).isEqualTo(2);
267	        assertThat(raceService.getResults(RACE).entries()).hasSize(1);
268	
269	        // 封榜重放返回首次的封榜响应
270	        raceService.addPenalty(RACE,
271	                new AddPenaltyRequest("p1", "a", "ADD_TIME", 10L, 2, "req-p1"));
272	        SealRaceRequest seal = new SealRaceRequest(3, "req-seal");
273	        ServiceResult sealed1 = raceService.sealRace(RACE, seal);
274	        ServiceResult sealed2 = raceService.sealRace(RACE, seal);
275	        assertThat(sealed2.status()).isEqualTo(sealed1.status());
276	        assertThat(json(sealed2.body())).isEqualTo(json(sealed1.body()));
277	    }
278	
279	    @Test
280	    void 同键异参返回409() {
281	        raceService.createRace(new CreateRaceRequest(RACE, "req-create"));
282	        raceService.registerRunner(RACE,
283	                new RegisterRunnerRequest("a", 100L, 1, "req-reg-a"));
284	
285	        assertThatThrownBy(() -> raceService.registerRunner(RACE,
286	                new RegisterRunnerRequest("b", 100L, 2, "req-reg-a")))
287	                .isInstanceOf(ConflictException.class)
288	                .hasMessageContaining("requestId");
289	        // expectedVersion 不同也算异参
290	        assertThatThrownBy(() -> raceService.registerRunner(RACE,
291	                new RegisterRunnerRequest("a", 100L, 9, "req-reg-a")))
292	                .isInstanceOf(ConflictException.class);
293	        // b 未被登记
294	        assertThat(raceService.getResults(RACE).entries()).hasSize(1);
295	    }
296	
297	    @Test
298	    void 业务失败不占用requestId键() {
299	        raceService.createRace(new CreateRaceRequest(RACE, "req-create"));
300	
301	        // 首次以错误版本请求，业务失败并随事务回滚，不占用 requestId
302	        assertThatThrownBy(() -> raceService.registerRunner(RACE,
303	                new RegisterRunnerRequest("a", 100L, 999, "req-a")))
304	                .isInstanceOf(ConflictException.class)
305	                .hasMessageContaining("版本冲突");
306	        assertThat(repository.findIdempotency("req-a")).isEmpty();
307	
308	        // 同一 requestId 以正确版本与参数重试应成功
309	        ServiceResult retry = raceService.registerRunner(RACE,
310	                new RegisterRunnerRequest("a", 100L, 1, "req-a"));
311	        assertThat(retry.status()).isEqualTo(201);
312	
313	        // 幂等表中只留下最终成功记录，无进行中占位
314	        Optional<IdempotencyRow> row = repository.findIdempotency("req-a");
315	        assertThat(row).isPresent();
316	        assertThat(row.get().responseStatus()).isEqualTo(201);
317	    }
318	
319	    private void seedSealedRace() {
320	        raceService.createRace(new CreateRaceRequest(RACE, "req-create"));
321	        raceService.registerRunner(RACE,
322	                new RegisterRunnerRequest("a", 100L, 1, "req-a"));
323	        raceService.sealRace(RACE, new SealRaceRequest(2, "req-seal"));
324	    }
325	}
