27	/**
28	 * H2 上的真实并发测试：乐观条件 UPDATE 串行化同赛事写操作，
29	 * 封榜与普通写互斥，同 requestId 并发只产生一次业务变更。
30	 */
31	@SpringBootTest
32	@Import(FixedClockTestConfig.class)
33	class RaceConcurrencyH2Test extends AbstractRaceH2Test {
34	
35	    private static final String RACE = "race-concurrent";
36	
37	    @Autowired
38	    private RaceService raceService;
39	
40	    @Test
41	    void 并发同版本登记仅一个成功且版本只加一() throws Exception {
42	        raceService.createRace(new CreateRaceRequest(RACE, "req-create"));
43	
44	        int threads = 10;
45	        ExecutorService pool = Executors.newFixedThreadPool(threads);
46	        CountDownLatch start = new CountDownLatch(1);
47	        AtomicInteger success = new AtomicInteger();
