package com.example.starter.race.api;

import com.example.starter.race.domain.EligibilityStatus;
import com.example.starter.race.domain.EntryStatus;
import com.fasterxml.jackson.annotation.JsonInclude;

import java.util.List;

/**
 * 成绩榜中的单个条目。
 *
 * @param bib                    参赛号
 * @param rank                   名次（并列同名次并跳号）；非 RANKED 为 null
 * @param status                RANKED / UNTIMED / MISSING_CHECKPOINT / DISQUALIFIED / WITHDRAWN / MEDICAL_HOLD
 * @param finishTimeMs          原始完赛耗时毫秒；计时缺失为 null
 * @param penaltyMs             生效加时合计毫秒数
 * @param totalTimeMs           总耗时毫秒；未排名为 null
 * @param checkpointCount       赛事检查点总数；未配置检查点为 0
 * @param coveredCheckpointCount 该选手已覆盖（未被排除）检查点数量
 * @param missingCheckpoints    缺失检查点代码，按检查点顺序排列；无缺失为空列表
 * @param eligibility           资格状态：ELIGIBLE / WITHDRAWN / MEDICAL_HOLD
 * @param excludedTimingCount   被排除、不参与排名的计时条数（暂停期间提交的分段）
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record ResultEntryResponse(
        String bib,
        Integer rank,
        EntryStatus status,
        Long finishTimeMs,
        long penaltyMs,
        Long totalTimeMs,
        int checkpointCount,
        int coveredCheckpointCount,
        List<String> missingCheckpoints,
        EligibilityStatus eligibility,
        int excludedTimingCount
) {
}

package com.example.starter.race.api;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 分段通过记录响应。
 *
 * @param timingId        全局唯一分段记录ID
 * @param bib             选手参赛号
 * @param checkpointCode  检查点代码
 * @param position        检查点顺序，从1连续递增
 * @param elapsedMillis   通过该检查点的累计耗时（毫秒）
 * @param exclusionReason 计时排除原因；null 表示正常计时，MEDICAL_HOLD 表示暂停期间被排除、不参与排名
 * @param createdAt       提交时间，UTC毫秒时间戳
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record CheckpointTimingResponse(
        String timingId,
        String bib,
        String checkpointCode,
        int position,
        long elapsedMillis,
        String exclusionReason,
        long createdAt
) {
}

package com.example.starter.race.api;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 单个选手在单个检查点上的分段明细。
 *
 * @param checkpointCode  检查点代码
 * @param position        检查点顺序，从1连续递增
 * @param elapsedMillis   通过累计耗时（毫秒）；尚未通过（缺失检查点）为 null
 * @param timingId        分段记录ID；尚未通过为 null
 * @param exclusionReason 计时排除原因；null 表示正常计时或缺失检查点，MEDICAL_HOLD 为暂停期间被排除
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record CheckpointPassResponse(
        String checkpointCode,
        int position,
        Long elapsedMillis,
        String timingId,
        String exclusionReason
) {

    /** 无排除原因的兼容构造器。 */
    public CheckpointPassResponse(
            String checkpointCode,
            int position,
            Long elapsedMillis,
            String timingId) {
        this(checkpointCode, position, elapsedMillis, timingId, null);
    }
}

